const C=DESIGN.colors;
const rgb=h=>({r:parseInt(h.slice(1,3),16)/255,g:parseInt(h.slice(3,5),16)/255,b:parseInt(h.slice(5,7),16)/255});
const paint=k=>[{type:'SOLID',color:rgb(C[k]||k)}];
const VAR={},STYLES={},COMPS={},ICONS={},map={},links=[],componentProps={};
const RUN='MemoA 2026.09.07';
function fill(n,k,prop='fills'){if(!k){n[prop]=[];return;}n[prop]=[figma.variables.setBoundVariableForPaint(paint(k)[0],'color',VAR[k])];}
function bind(n,field,value){const v=VAR[field+'/'+value];if(v)n.setBoundVariable(field,v);else n[field]=value;}
async function loadFonts(){const available=await figma.listAvailableFontsAsync();const family=available.some(f=>f.fontName.family==='Noto Sans KR')?'Noto Sans KR':available.some(f=>f.fontName.family==='Noto Sans CJK KR')?'Noto Sans CJK KR':null;if(!family)throw Error('Noto Sans KR 글꼴을 설치한 뒤 다시 실행해 주세요.');const fonts={};for(const [weight,style] of [[400,'Regular'],[500,'Medium'],[700,'Bold']]){const f=available.find(f=>f.fontName.family===family&&f.fontName.style===style);if(!f)throw Error(family+' '+style+' 글꼴이 필요합니다.');await figma.loadFontAsync(f.fontName);fonts[weight]=f.fontName;}return fonts;}
let FONT;
function styleText(n,s){n.fontName=FONT[s.weight||400];n.fontSize=s.size||16;n.lineHeight={unit:'PIXELS',value:s.h/s.text.split('\n').length};n.textAutoResize='HEIGHT';n.resize(s.w,s.h);n.characters=s.text;n.textAlignHorizontal=(s.align||'left').toUpperCase();fill(n,s.color||'ink');const st=STYLES[(s.size||16)+'/'+(s.weight||400)];if(st)n.textStyleId=st.id;}
function setProperties(inst,s){const refs=componentProps[s.component];if(!refs)return;const ov=s.overrides||{};const vals={};for(const [key,id] of Object.entries(refs)){if(ov[key]!==undefined&&key!=='icon')vals[id]=typeof ov[key]==='boolean'?ov[key]:String(ov[key]);}if(refs.icon&&ov.icon)vals[refs.icon]=ICONS[ov.icon].id;if(Object.keys(vals).length)inst.setProperties(vals);}
async function build(s,parent,allowComponents=true){let n;
if(allowComponents&&s.component&&COMPS[s.component]){n=COMPS[s.component].createInstance();parent.appendChild(n);n.resize(s.w,s.h);setProperties(n,s);}
else if(s.kind==='text'){n=figma.createText();parent.appendChild(n);styleText(n,s);}
else if(s.kind==='icon'){n=ICONS[s.icon].createInstance();parent.appendChild(n);n.resize(s.w,s.h);for(const v of n.findAll(x=>'fills'in x)){if(v.type==='VECTOR'){if(v.fills.length)fill(v,s.color);if(v.strokes.length)fill(v,s.color,'strokes');}}}
else{n=figma.createFrame();if(s.layout)n.layoutMode=s.layout;parent.appendChild(n);n.resize(s.w,s.h);if(s.layout){n.layoutSizingHorizontal='FIXED';n.layoutSizingVertical='FIXED';}fill(n,s.bg);if(s.stroke){fill(n,s.stroke,'strokes');n.strokeWeight=s.strokeWidth||1;n.strokeAlign='INSIDE';}if(s.radius)bind(n,'cornerRadius',s.radius);if(s.opacity)n.opacity=s.opacity;if(s.layout){n.primaryAxisSizingMode='FIXED';n.counterAxisSizingMode='FIXED';bind(n,'itemSpacing',s.gap||0);for(const f of ['paddingLeft','paddingRight','paddingTop','paddingBottom'])bind(n,f,s.pad||0);n.counterAxisAlignItems=s.align==='CENTER'?'CENTER':'MIN';}n.clipsContent=!!s.scroll;if(s.scroll)n.overflowDirection='VERTICAL';for(const c of s.children||[])await build(c,n,allowComponents);}
n.name=s.name;if(!parent.layoutMode||parent.layoutMode==='NONE'){n.x=s.x||0;n.y=s.y||0;}if(!s.layout&&n.type!=='TEXT'&&'constraints'in n)n.constraints={horizontal:'MIN',vertical:'MIN'};if(n.type==='TEXT')n.constraints={horizontal:'STRETCH',vertical:'MIN'};if(s.go)links.push({node:n,go:s.go});return n;}
async function makeTokens(){const existing=await figma.variables.getLocalVariableCollectionsAsync();if(existing.some(c=>c.name===RUN+' / 색상'))throw Error('이미 MemoA 디자인을 가져왔습니다. 중복 생성을 막기 위해 종료합니다.');const primitives=figma.variables.createVariableCollection(RUN+' / 기본값');const colors=figma.variables.createVariableCollection(RUN+' / 색상');const dimensions=figma.variables.createVariableCollection(RUN+' / 간격과 모양');colors.renameMode(colors.defaultModeId,'Light');for(const [key,hex] of Object.entries(C)){const p=figma.variables.createVariable('palette/'+key,primitives,'COLOR');p.setValueForMode(primitives.defaultModeId,rgb(hex));p.scopes=[];p.setVariableCodeSyntax('WEB',`var(--memoa-palette-${key})`);p.setVariableCodeSyntax('ANDROID',`MemoAPalette.${key}`);const v=figma.variables.createVariable('color/'+key,colors,'COLOR');v.setValueForMode(colors.defaultModeId,{type:'VARIABLE_ALIAS',id:p.id});v.scopes=['FRAME_FILL','SHAPE_FILL','TEXT_FILL','STROKE_COLOR'];v.setVariableCodeSyntax('WEB',`var(--memoa-${key})`);v.setVariableCodeSyntax('ANDROID',`MemoAColors.${key}`);VAR[key]=v;}
for(const field of ['cornerRadius','itemSpacing','paddingLeft','paddingRight','paddingTop','paddingBottom'])for(const value of [0,4,6,8,10,12,14,15,16,20,24,26,28,40]){const v=figma.variables.createVariable(field+'/'+value,dimensions,'FLOAT');v.setValueForMode(dimensions.defaultModeId,value);v.scopes=[field==='cornerRadius'?'CORNER_RADIUS':'GAP'];v.setVariableCodeSyntax('WEB',`var(--memoa-${field}-${value})`);v.setVariableCodeSyntax('ANDROID',`MemoADimensions.dp${value}`);VAR[field+'/'+value]=v;}
for(const [size,weight] of [[14,400],[14,500],[14,700],[16,400],[16,500],[18,500],[18,700],[20,700],[22,700],[24,700],[26,700],[28,700],[36,700]]){const st=figma.createTextStyle();st.name=`MemoA/${size}sp/${weight}`;st.fontName=FONT[weight];st.fontSize=size;st.lineHeight={unit:'PIXELS',value:size===14?20:size===16?24:Math.ceil(size*1.4)};STYLES[size+'/'+weight]=st;}}
async function makeIcons(page){let i=0;for(const [name,svg] of Object.entries(DESIGN.icons)){const c=figma.createComponent();page.appendChild(c);c.name='Icon/'+name;c.resize(24,24);c.fills=[];c.x=40+(i%12)*80;c.y=120+Math.floor(i/12)*80;const v=figma.createNodeFromSvg(svg);c.appendChild(v);v.x=0;v.y=0;for(const a of v.findAll(x=>x.type==='VECTOR')){if(a.fills.length)fill(a,'ink');if(a.strokes.length)fill(a,'ink','strokes');}c.description='Lucide icon. SVG source from bundled lucide package. 24dp visual inside 48dp touch target.';ICONS[name]=c;i++;}}
async function makeComponents(page){let y=520;for(const [key,s] of Object.entries(DESIGN.components)){let source={...s,x:40,y:0,go:null,component:null};if(key.startsWith('Button/')){const label=s.children.find(n=>n.kind==='text');source={...source,layout:'HORIZONTAL',gap:8,pad:12,align:'CENTER',children:[{kind:'icon',name:'선행 아이콘',icon:'Sparkles',color:label.color,w:20,h:20},{...label,name:'버튼 문구',x:0,y:0}]};}const base=await build(source,page,false);const c=figma.createComponentFromNode(base);c.name=key;c.x=40;c.y=y;if(key.startsWith('Button/')){c.primaryAxisAlignItems='CENTER';c.paddingTop=14;c.paddingBottom=14;const t=c.findAllWithCriteria({types:['TEXT']})[0];t.textAutoResize='WIDTH_AND_HEIGHT';}c.description='MemoA 공통 컴포넌트. 한국어 14sp 이상, 터치 영역 48dp 이상.';COMPS[key]=c;y+=s.h+64;}
for(const family of ['Button','Field','EventCard','NavItem']){const entries=Object.entries(COMPS).filter(([k])=>k.startsWith(family+'/'));const nodes=entries.map(([k,c])=>{c.name='State='+k.split('/')[1];return c;});const set=figma.combineAsVariants(nodes,page);set.name=family;set.description='MemoA '+family+' 상태 변형';const idx=['Button','Field','EventCard','NavItem'].indexOf(family);set.x=40+idx*500;set.y=540;let cy=24;for(const n of nodes){n.x=24;n.y=cy;cy+=n.height+28;}set.resize(420,cy);const refs={};const mapping=family==='Button'?{label:0}:family==='Field'?{label:0,value:1}:family==='EventCard'?{tag:0,meta:1,title:2,place:3}:{label:0};const first=nodes[0].findAllWithCriteria({types:['TEXT']});for(const [name,idx] of Object.entries(mapping)){refs[name]=set.addComponentProperty(name,'TEXT',first[idx].characters);}if(family==='Button'||family==='NavItem')refs.icon=set.addComponentProperty('icon','INSTANCE_SWAP',ICONS[family==='Button'?'Sparkles':'House'].id);if(family==='Button')refs.showIcon=set.addComponentProperty('showIcon','BOOLEAN',false);for(const [key,c] of entries){const texts=c.findAllWithCriteria({types:['TEXT']});for(const [name,idx] of Object.entries(mapping))texts[idx].componentPropertyReferences={characters:refs[name]};if(refs.icon){const ico=c.findAllWithCriteria({types:['INSTANCE']})[0];ico.componentPropertyReferences={mainComponent:refs.icon,...(refs.showIcon?{visible:refs.showIcon}:{})};if(refs.showIcon)ico.visible=false;}componentProps[key]=refs;}}}
async function foundations(page){const doc={kind:'frame',name:'MemoA / 디자인 시스템',w:1440,h:900,bg:'bg',children:[{kind:'text',name:'브랜드',text:'MemoA',w:1100,h:90,size:64,weight:700,color:'blue',x:80,y:72},{kind:'text',name:'슬로건',text:'메시지를 일정으로, 간편하게',w:1100,h:56,size:36,weight:700,color:'ink',x:80,y:168},{kind:'text',name:'설명',text:'Android Material 3 기반 UI/UX  ·  360 × 800dp\n메시지 입력 → AI 분석 → 사용자 확인·수정 → 저장 → 캘린더와 목록',w:1240,h:68,size:24,weight:400,color:'muted',x:80,y:260},{kind:'text',name:'타이포그래피',text:'Noto Sans KR\n본문 14–16sp · 제목 18–28sp · 버튼 16sp\n터치 영역 최소 48dp · 시간 표기 HH:mm',w:900,h:108,size:24,weight:400,color:'ink',x:80,y:520},{kind:'text',name:'UX 원칙',text:'AI는 제안하고, 사용자가 확정합니다.\n모호한 날짜·시간은 확인 필요로 표시 · 알림 접근은 선택 사항\n직접 입력과 공유는 권한 없이도 사용 가능',w:1240,h:108,size:24,weight:400,color:'ink',x:80,y:700}]};let i=0;for(const k of ['blue','blueSoft','mint','ink','muted','amberSoft']){doc.children.push({kind:'frame',name:k,w:184,h:100,x:80+i*204,y:372,bg:k,radius:20,children:[{kind:'text',name:k,text:k+'\n'+C[k],w:152,h:48,size:16,weight:500,color:['blue','ink','muted'].includes(k)?'surface':'ink',x:16,y:24}]});i++;}await build(doc,page,false);}
async function run(){FONT=await loadFonts();await makeTokens();let cover=figma.root.children.find(p=>p.name===RUN+' / 안내');if(!cover){cover=figma.root.children.length===1&&figma.root.children[0].name==='Page 1'?figma.root.children[0]:figma.createPage();cover.name=RUN+' / 안내';}const componentPage=figma.createPage();componentPage.name=RUN+' / 컴포넌트';await figma.setCurrentPageAsync(componentPage);await makeIcons(componentPage);await makeComponents(componentPage);await figma.setCurrentPageAsync(cover);await foundations(cover);const page=figma.createPage();page.name=RUN+' / 화면';await figma.setCurrentPageAsync(page);let rowY=100;const groups=[...new Set(DESIGN.screens.map(s=>s.group))];for(const group of groups){const title=figma.createText();title.fontName=FONT[700];title.characters=group;title.fontSize=36;fill(title,'ink');title.x=40;title.y=rowY;rowY+=80;const ss=DESIGN.screens.filter(s=>s.group===group);for(let i=0;i<ss.length;i++){const s=ss[i],n=await build({...s,x:40+(i%8)*420,y:rowY+Math.floor(i/8)*900},page);n.clipsContent=true;map[s.key]=n;}rowY+=Math.ceil(ss.length/8)*900+100;}
for(const {node,go} of links){if(!map[go])continue;await node.setReactionsAsync([{trigger:{type:'ON_CLICK'},actions:[{type:'NODE',destinationId:map[go].id,navigation:'NAVIGATE',transition:{type:'DISSOLVE',duration:0.18,easing:{type:'EASE_OUT'}},resetScrollPosition:true}]}]);}
for(const s of DESIGN.screens)if(s.next)await map[s.key].setReactionsAsync([{trigger:{type:'AFTER_TIMEOUT',timeout:s.key==='analyzing'?2.4:s.key==='splash'?.8:1},actions:[{type:'NODE',destinationId:map[s.next].id,navigation:'NAVIGATE',transition:{type:'DISSOLVE',duration:.2,easing:{type:'EASE_OUT'}}}]}]);page.flowStartingPoints=[{nodeId:map.home.id,name:'메시지를 일정으로'},{nodeId:map.splash.id,name:'처음 시작하기'},{nodeId:map['result-review'].id,name:'확인 필요 상태'}];figma.viewport.scrollAndZoomIntoView([map.home,map.input,map.result]);figma.closePlugin(DESIGN.screens.length+'개 화면과 디자인 시스템을 가져왔어요.');}
run().catch(e=>{figma.closePlugin('가져오기 실패: '+e.message);});
